fn correct_index(flags: &[bool]) -> Result<usize, String> {
    let marked: Vec<usize> = flags
        .iter()
        .enumerate()
        .filter(|(_, c)| **c)
        .map(|(i, _)| i)
        .collect();
    match marked.as_slice() {
        [one] => Ok(*one),
        [] => Err("none marked".to_owned()),
        many => Err(format!("{} marked", many.len())),
    }
}

fn main() { println!("{:?}", correct_index(&[false, true, true, false])); }

fn pick(marked: Vec<usize>) -> Result<usize, String> {
    match marked.as_slice() {
        [one, ..] => Ok(*one),
        [] => Err("none marked".to_owned()),
        many => Err(format!("{} marked", many.len())),
    }
}

fn validate(output: Output) -> Result<Question, String> {
    if !(3..=5).contains(&output.options.len()) {
        return Err("there must be 3 to 5 options".to_owned());
    }
    let correct = output.options.iter().position(|o| o.correct).unwrap_or(0);
    Ok(Question {
        options: output.options,
        correct,
    })
}

